async function(mode, file) {
  await liveFixTab.click(`role/tab[name="${mode}" exact]`);
  return await liveFixTab.run(async ({ page }, path, expectedMode) => {
    await page.waitForFunction((mode) => document.querySelector('[data-testid="market-charts"]')?.getAttribute("data-mode") === mode, { timeout: 15000 }, expectedMode);
    const response = page.waitForResponse((r) => r.url().endsWith("/api/v1/visualization") && r.status() === 200 && JSON.parse(r.request().postData() || "{}").recenter === true, { timeout: 30000 });
    await page.click('[data-testid="view-recenter"]');
    const received = await response, request = JSON.parse(received.request().postData()), grid = await received.json();
    await page.waitForFunction((id) => document.querySelector('[data-testid="market-charts"]')?.getAttribute("data-painted-view-id") === id, { timeout: 30000 }, grid.view_id);
    await page.waitForFunction(() => {
      const s = document.querySelector(".ladder-scroll");
      if (!s)
        return false;
      const b = s.getBoundingClientRect();
      return ["bid", "ask"].every((side) => [...s.querySelectorAll(`tr.${side}`)].some((row) => {
        const r = row.getBoundingClientRect();
        return r.bottom > b.top && r.top < b.bottom;
      }));
    }, { timeout: 30000 });
    const observed = await page.evaluate(async (id) => {
      const f = await (await fetch(`/api/v1/sessions/${id}`)).json();
      const el = document.querySelector('[data-testid="market-charts"]'), area = document.querySelector(".ladder-scroll").getBoundingClientRect();
      const visible = (side) => [...document.querySelectorAll(`.ladder tr.${side}`)].some((row) => {
        const r = row.getBoundingClientRect();
        return r.bottom > area.top && r.top < area.bottom;
      });
      return { frame: { session_id: f.session_id, selection: f.selection, status: f.status, source: f.source, health: f.health, book: f.book, error: f.error, telemetry: f.telemetry, tape_length: f.analytics?.tape.length, newest_prints: f.analytics?.tape.slice(-3) }, surface: { source: document.querySelector(".source-banner")?.textContent, chart: document.querySelector(".chart-status")?.textContent, attributes: Object.fromEntries([...el.attributes].map((a) => [a.name, a.value])), instrumentButtons: document.querySelectorAll("[data-instrument-id]").length, elementCount: document.querySelectorAll("*").length, bothSidesVisible: visible("bid") && visible("ask"), errors: [...document.querySelectorAll('[role="alert"]')].map((e) => e.textContent) } };
    }, request.session_id);
    if (observed.surface.attributes["data-mode"] !== expectedMode || !observed.surface.bothSidesVisible || observed.frame.status !== "live" || observed.frame.telemetry.overflows)
      throw Error("Native live surface did not settle correctly");
    await page.screenshot({ path, fullPage: true });
    return { ...observed, grid, screenshot: path, request };
  }, { args: [`${evRoot}${file}`, mode], timeout: 110 });
}
